func (t *SmokeBitList8) MarshalSSZTo(buf []byte) (dst []byte, err error) {
	dst = buf
	if t == nil {
		t = new(SmokeBitList8)
	}
	vlen := len(*t)
	bval := []byte((*t)[:])
	if vlen == 0 {
		bval = []byte{0x01}
	} else if bval[vlen-1] == 0x00 {
		return nil, sszutils.ErrBitlistNotTerminatedFn()
	}
	if vlen > 0 {
		bitCount := uint64(vlen-1)*8 + uint64(bits.Len8(bval[vlen-1])) - 1
		if bitCount > 8 {
			return nil, sszutils.ErrBitlistLengthFn(bitCount, 8)
		}
	}
	dst = append(dst, bval...)
	return dst, nil
}

