// SizeSSZ returns the SSZ encoded size of the *ExtMixed.
func (t *ExtMixed) SizeSSZ() int {
	var size int64
	if t == nil {
		t = new(ExtMixed)
	}
	// Field #0 'Ints' offset (4 bytes)
	// Field #1 'Floats' static (36 bytes)
	// Field #2 'Opts' offset (4 bytes)
	// Field #3 'Big' offset (4 bytes)
	// Field #4 'Wrapped' offset (4 bytes)
	size += 52
	{ // Dynamic field #0 'Ints'
		s1 := int64(t.Ints.SizeSSZ())
		if s1 < 0 {
			return -1
		}
		size += s1
	}
	{ // Dynamic field #2 'Opts'
		t2 := t.Opts
		vlen := len(t2)
		size += int64(vlen) * 4 // Offsets
		for i1 := range vlen {
			s2 := int64(t2[i1].SizeSSZ())
			if s2 < 0 {
				return -1
			}
			size += s2
		}
	}
	{ // Dynamic field #3 'Big'
		s3 := int64(t.Big.SizeSSZ())
		if s3 < 0 {
			return -1
		}
		size += s3
	}
	{ // Dynamic field #4 'Wrapped'
		s4 := int64(t.Wrapped.SizeSSZ())
		if s4 < 0 {
			return -1
		}
		size += s4
	}
	if uint64(size) > sszutils.MaxSszSize {
		return -1
	}
	return int(size)
}

// SizeSSZDyn returns the SSZ encoded size of the *ExtMixed using dynamic specifications.
func (t *ExtMixed) SizeSSZDyn(_ sszutils.DynamicSpecs) int {
	return t.SizeSSZ()
}

// HashTreeRoot computes the SSZ hash tree root of the *ExtMixed.
func (t *ExtMixed) HashTreeRoot() (root [32]byte, err error) {
	err = hasher.WithDefaultHasher(func(hh sszutils.HashWalker) (err error) {
		err = t.HashTreeRootWith(hh)
		if err == nil {
			root, err = hh.HashRoot()
		}
		return
	})
	return
}

// HashTreeRootWith computes the SSZ hash tree root of the *ExtMixed using the given hash walker.
func (t *ExtMixed) HashTreeRootWith(hh sszutils.HashWalker) error {
	if t == nil {
		t = new(ExtMixed)
	}
	idx := hh.StartTree(sszutils.TreeTypeNone)
	{ // Field #0 'Ints'
		t := t.Ints
		if err := t.HashTreeRootWith(hh); err != nil {
			return sszutils.ErrorWithPath(err, "Ints")
		}
	}
	{ // Field #1 'Floats'
		t := &t.Floats
		if err := t.HashTreeRootWith(hh); err != nil {
			return sszutils.ErrorWithPath(err, "Floats")
		}
	}
	{ // Field #2 'Opts'
		t := t.Opts
		vlen := uint64(len(t))
		if vlen > 5 {
			return sszutils.ErrorWithPath(sszutils.ErrListLengthFn(vlen, 5), "Opts")
		}
		idx := hh.StartTree(sszutils.TreeTypeBinary)
		for idx1 := range len(t) {
			t := &t[idx1]
			if err := t.HashTreeRootWith(hh); err != nil {
				return sszutils.ErrorWithPathf(err, "Opts[%d]", idx1)
			}
			if (idx1+1)%256 == 0 {
				hh.Collapse()
			}
		}
		hh.MerkleizeWithMixin(idx, vlen, sszutils.CalculateLimit(5, vlen, 32))
	}
	{ // Field #3 'Big'
		t := &t.Big
		if err := t.HashTreeRootWith(hh); err != nil {
			return sszutils.ErrorWithPath(err, "Big")
		}
	}
	{ // Field #4 'Wrapped'
		t := &t.Wrapped
		if err := t.HashTreeRootWith(hh); err != nil {
			return sszutils.ErrorWithPath(err, "Wrapped")
		}
	}
	hh.Merkleize(idx)
	return nil
}

